"""Background pasteboard observation independent of Qt window activation."""
import sys
from clipx.platforms.base import Result, Status

SELF_TYPE = 'org.clipx.self'
PRIVATE_TYPES = frozenset((SELF_TYPE, 'org.nspasteboard.ConcealedType',
                           'org.nspasteboard.TransientType', 'org.nspasteboard.AutoGeneratedType',
                           'com.agilebits.onepassword'))
TEXT_TYPE = 'public.utf8-plain-text'


class MacOSClipboardDriver:
    def __init__(self, pasteboard=None):
        self._pasteboard = pasteboard
        self._last_change = None
        self._stopped = None

    @property
    def pasteboard(self):
        if self._pasteboard is None:
            from AppKit import NSPasteboard
            self._pasteboard = NSPasteboard.generalPasteboard()
        return self._pasteboard

    def listener_command(self, database):
        return [sys.executable, '-m', 'clipx.capture', str(database), '--watch-macos']

    def poll(self, capture):
        board = self.pasteboard
        count = board.changeCount()
        if count == self._last_change:
            return None
        types = set(board.types() or ())
        if types & PRIVATE_TYPES or not types:
            self._last_change = count
            capture.reset()
            return Result()
        text = board.stringForType_(TEXT_TYPE)
        if board.changeCount() != count:
            return None  # Retry the new generation, never persist an inconsistent read.
        self._last_change = count
        if text is None:
            if TEXT_TYPE in types:
                return Result(Status.PERMISSION_REQUIRED,
                              'Leitura do clipboard indisponível. Verifique as permissões do macOS.')
            return Result()
        capture.save(str(text))
        return Result()

    def write_text(self, text):
        try:
            board = self.pasteboard
            board.clearContents()
            if not board.setString_forType_(text, TEXT_TYPE):
                return Result(Status.ERROR, 'O macOS não confirmou a cópia do texto.')
            board.setString_forType_('ClipX', SELF_TYPE)
            return Result()
        except Exception as exc:
            return Result(Status.ERROR, f'Não foi possível copiar: {exc}')

    def start_observation(self, capture, stopped, report):
        import objc
        from Foundation import NSRunLoop, NSDate
        self._stopped = stopped
        last_status = None
        while not stopped.is_set():
            with objc.autorelease_pool():
                try:
                    result = self.poll(capture)
                    if result is not None and result != last_status:
                        report(result)
                        last_status = result
                except Exception as exc:
                    result = Result(Status.UNAVAILABLE, f'Captura do macOS indisponível: {exc}')
                    if result != last_status:
                        report(result)
                        last_status = result
                NSRunLoop.currentRunLoop().runUntilDate_(NSDate.dateWithTimeIntervalSinceNow_(0.01))
            stopped.wait(0.24)

    def stop_observation(self):
        if self._stopped is not None:
            self._stopped.set()
